targets.rawSql:
SELECT
    $__timeInterval(datetime) AS time,
    ${eselect},
    count(*) AS "Total"
FROM ${table}
WHERE $__timeFilter(datetime)
  AND ${generalescaping}
  AND $__adHocFilter()
  AND username != '-'
GROUP BY time, ${eselect}
ORDER BY time ASC, ${eselect}
SETTINGS hdx_query_max_execution_time=60,
         hdx_query_admin_comment='db=${__dashboard}; dp=Users per APP; du=${__user.login}';
